    ($SATQ$284303f1$SATQ$, $SATQ$d76b8468-eb1c-4309-9278-5eda6d2d9b3e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Problem-Solving and Data Analysis$SATQ$, $SATQ$Q$SATQ$, $SATQ$Q.B.$SATQ$, $SATQ$Percentages$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">There are <math alttext="250"><mn>250</mn>
</math> trees in a park. Of these trees, <math alttext="6 percent sign"><mn>6</mn><mo>%</mo></math> are birch trees. How many birch trees are in the park?</p>$SATQ$, $SATQ$[{"id":"aa187102-187a-4852-882e-e94c6df3d4ac","content":"<p><math alttext=\"6\"><mn>6</mn>\n</math></p>"},{"id":"c23123a1-2a4e-4475-a01d-5dbaa89158ec","content":"<p><math alttext=\"15\"><mn>15</mn>\n</math></p>"},{"id":"2c0410f6-9515-4d74-91d8-29b414112226","content":"<p><math alttext=\"75\"><mn>75</mn>\n</math></p>"},{"id":"881c70f1-53d0-438f-bb17-3de948d7cda4","content":"<p><math alttext=\"244\"><mn>244</mn>\n</math></p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["c23123a1-2a4e-4475-a01d-5dbaa89158ec"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">Choice B is correct. It's given that there are <math alttext="250"><mn>250</mn>
</math> trees in a park and of these trees, <math alttext="6 percent sign"><mn>6</mn><mo>%</mo></math> are birch trees. The number of birch trees in the park can be calculated by multiplying the number of trees in the park by <math alttext="StartFraction 6 Over 100 EndFraction"><mfrac><mn>6</mn><mn>100</mn></mfrac></math>. Therefore, the number of birch trees in the park is <math alttext="250 left parenthesis StartFraction 6 Over 100 EndFraction right parenthesis"><mn>250</mn><mfenced><mfrac><mn>6</mn><mn>100</mn></mfrac></mfenced></math>, or <math alttext="15"><mn>15</mn>
</math>.</p>
<p style="text-align: left;">Choice A is incorrect. This is the percentage of trees in the park that are birch trees, not the number of birch trees in the park.</p>
<p style="text-align: left;">Choice C is incorrect. This is <math alttext="30 percent sign"><mn>30</mn><mo>%</mo></math>, not <math alttext="6 percent sign"><mn>6</mn><mo>%</mo></math>, of <math alttext="250"><mn>250</mn>
</math>.</p>
<p style="text-align: left;">Choice D is incorrect and may result from conceptual or calculation errors.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"284303f1","external_id":"d76b8468-eb1c-4309-9278-5eda6d2d9b3e","disclosed_item_id":null,"source":"qbank","vaultid":null,"uId":"84d94bc3-f77d-4645-8498-54327390fc34","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"Q","domain":"Problem-Solving and Data Analysis","skill_cd":"Q.B.","skill_desc":"Percentages","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":null,"stem":"<p style=\"text-align: left;\">There are <math alttext=\"250\"><mn>250</mn>\n</math> trees in a park. Of these trees, <math alttext=\"6 percent sign\"><mn>6</mn><mo>%</mo></math> are birch trees. How many birch trees are in the park?</p>","answerOptions":[{"id":"aa187102-187a-4852-882e-e94c6df3d4ac","content":"<p><math alttext=\"6\"><mn>6</mn>\n</math></p>"},{"id":"c23123a1-2a4e-4475-a01d-5dbaa89158ec","content":"<p><math alttext=\"15\"><mn>15</mn>\n</math></p>"},{"id":"2c0410f6-9515-4d74-91d8-29b414112226","content":"<p><math alttext=\"75\"><mn>75</mn>\n</math></p>"},{"id":"881c70f1-53d0-438f-bb17-3de948d7cda4","content":"<p><math alttext=\"244\"><mn>244</mn>\n</math></p>"}],"keys":["c23123a1-2a4e-4475-a01d-5dbaa89158ec"],"correct_answer":["B"],"rationale":"<p style=\"text-align: left;\">Choice B is correct. It's given that there are <math alttext=\"250\"><mn>250</mn>\n</math> trees in a park and of these trees, <math alttext=\"6 percent sign\"><mn>6</mn><mo>%</mo></math> are birch trees. The number of birch trees in the park can be calculated by multiplying the number of trees in the park by <math alttext=\"StartFraction 6 Over 100 EndFraction\"><mfrac><mn>6</mn><mn>100</mn></mfrac></math>. Therefore, the number of birch trees in the park is <math alttext=\"250 left parenthesis StartFraction 6 Over 100 EndFraction right parenthesis\"><mn>250</mn><mfenced><mfrac><mn>6</mn